def solution(signals):
    from math import gcd
    from functools import reduce

    def lcm(a, b):
        return a * b // gcd(a, b)

    total_cycle = reduce(lcm, [signal[0] + signal[1] + signal[2] for signal in signals])

    for t in range(total_cycle):
        if all((t % (signal[0] + signal[1] + signal[2])) >= signal[0] and (t % (signal[0] + signal[1] + signal[2])) < (signal[0] + signal[1]) for signal in signals):
            return t

    return -1

def solution(signals):
