        if time > 10000:
            return -1
        if all((time % signal) == (signal // 2) for signal in signals):
            return time
        return check_yellow(time + 1)

    return check_yellow(0)

def solution(message, spoiler_ranges):
    from bisect import bisect_left, bisect_right

    n = len(message)
    spoiler = [0] * (n + 1)

    for start, end in spoiler_ranges:
        spoiler[start] += 1
        if end + 1 <= n:
            spoiler[end + 1] -= 1

    for i in range(1, n + 1):
        spoiler[i] += spoiler[i - 1]

    important_words = set()
    for i in range(n):
        if spoiler[i] == 0:
            important_words.add(message[i])

    return len(important_words)

def solution(message, spoiler_ranges):
    def is_spoiler(word):
        return word in spoiler_words

    def count_important_words(words, index):
        if index >= len(words):
            return 0
        word = words[index]
        if is_spoiler(word):
            return 1 + count_important_words(words, index + 1)
        return count_important_words(words, index + 1)

    spoiler_words = set(word for start, end in spoiler_ranges for word in message[start:end + 1].split())
    words = message.split()
    return count_important_words(words, 0)

def solution(n, w, num):
    if num < 1 or num > n:
        return 0
    if num % 2 == 0:
        return 1 + solution(n, w, num - 1)
    return solution(n, w, num - 1)

