                if all(park[x][y] == '-1' for x in range(i, i + mat_size) for y in range(j, j + mat_size)):
                    return True
        return False

    left, right = 1, min(len(park), len(park[0]), max(mats))
    answer = 0

    while left <= right:
        mid = (left + right) // 2
        if mid in mats and can_place(mid):
            answer = mid
            left = mid + 1
        else:
            right = mid - 1

    return answer

def solution(mats, park):
    def can_place(mat, x, y):
        return 0 <= x < len(mat) and 0 <= y < len(mat[0]) and mat[x][y] == 0

    def dfs(mat, x, y, size):
        if not can_place(mat, x, y):
            return size - 1
        mat[x][y] = 1
        max_size = size
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            max_size = max(max_size, dfs(mat, x + dx, y + dy, size + 1))
        mat[x][y] = 0
        return max_size

    max_area = -1
    for i in range(len(mats)):
        for j in range(len(mats[0])):
            if mats[i][j] == 0:
                max_area = max(max_area, dfs(mats, i, j, 1))

    return max_area if max_area > 0 else -1

def solution(friends, gifts):
    def calculate_gift_index(friends, gifts, index, gift_index):
        if index >= len(friends):
            return gift_index
        current_friend = friends[index]
        current_gift_count = 0
        for gift in gifts:
            if gift == current_friend:
                current_gift_count += 1
        gift_index[current_friend] = current_gift_count
        return calculate_gift_index(friends, gifts, index + 1, gift_index)

    gift_index = {}
    calculate_gift_index(friends, gifts, 0, gift_index)

    max_gifts = -1
    recipient = None
    for friend in gift_index:
        if gift_index[friend] > max_gifts:
            max_gifts = gift_index[friend]
            recipient = friend

    return recipient

