def solution(bandage, health, attacks):
    def simulate(health, attacks, index):
        if health <= 0:
            return False
        if index >= len(attacks):
            return True
        attack_time = attacks[index]
        if attack_time < bandage:
            return simulate(health - 1, attacks, index + 1)
        else:
            new_health = min(health + 1, bandage)
            return simulate(new_health, attacks, index + 1)

    return simulate(health, attacks, 0)

