            max_y = max(max_y, y + 1)
        return find_coordinates(wallpaper, x, y + 1, min_x, min_y, max_x, max_y)

    min_x, min_y, max_x, max_y = find_coordinates(wallpaper)
    return [min_x, min_y, max_x, max_y]

