def solution(today, terms, privacies):
    term_dict = {t.split()[0]: int(t.split()[1]) for t in terms}
    today_date = list(map(int, today.split('.')))

    def is_expired(date, term):
        year, month, day = date
        month += term
        if month > 12:
            year += month // 12
            month = month % 12
        if month == 0:
            month = 12
            year -= 1
        return (year, month, day) < (today_date[0], today_date[1], today_date[2])

    def find_expired_privacies(index, expired):
        if index == len(privacies):
            return expired
        p_date, p_term = privacies[index].split()
        p_date = list(map(int, p_date.split('.')))
        if is_expired(p_date, term_dict[p_term]):
            expired.append(index + 1)
        return find_expired_privacies(index + 1, expired)

    return find_expired_privacies(0, [])

