def solution(N, stages):
    user_count = len(stages)
    stage_counts = [0] * (N + 2)

    for stage in stages:
        if stage <= N + 1:
            stage_counts[stage] += 1

    failure_rates = []
    for i in range(1, N + 1):
        if user_count > 0:
            failure_rate = stage_counts[i] / user_count
            failure_rates.append((failure_rate, i))
            user_count -= stage_counts[i]
        else:
            failure_rates.append((0, i))

    failure_rates.sort(key=lambda x: (-x[0], x[1]))
    return [stage for rate, stage in failure_rates]

