    end_times = []

    for start, end in book_time:
        start_hour, start_minute = map(int, start.split(':'))
        end_hour, end_minute = map(int, end.split(':'))
        end_time = end_hour * 60 + end_minute + 10

        if not end_times or end_times[0] > start_hour * 60 + start_minute:
            end_times.append(end_time)
        else:
            end_times[0] = end_time

        end_times.sort()

    return len(end_times)

def solution(book_time):
    book_time.sort(key=lambda x: x[0])

    def count_rooms(index, rooms):
        if index >= len(book_time):
            return rooms

        start_time = book_time[index][0]
        end_time = book_time[index][1]

        available_rooms = sum(1 for room_end in rooms if room_end <= start_time)

        if available_rooms > 0:
            rooms = [room_end for room_end in rooms if room_end > start_time]
        else:
            rooms.append(end_time)

        rooms[-1] = end_time

        return count_rooms(index + 1, rooms)

    return count_rooms(0, [])

