def solution(x, y, n):
    def dfs(current, count, visited):
        if current > y or current in visited:
            return float('inf')
        if current == y:
            return count
        visited.add(current)
        add_n = dfs(current + n, count + 1, visited)
        multiply_2 = dfs(current * 2, count + 1, visited)
        multiply_3 = dfs(current * 3, count + 1, visited)
        visited.remove(current)
        return min(add_n, multiply_2, multiply_3)

    result = dfs(x, 0, set())
    return result if result != float('inf') else -1

def solution(x, y, n):
    from collections import deque
    queue = deque([(x, 0)])
    visited = set([x])

    while queue:
        current, steps = queue.popleft()

        if current == y:
            return steps

        next_values = [current + n, current * 2, current * 3]

        for next_value in next_values:
            if next_value <= y and next_value not in visited:
                visited.add(next_value)
                queue.append((next_value, steps + 1))

    return -1

def solution(x, y, n):
