def solution(cap, n, deliveries, pickups):
    def dfs(index, current_load_deliveries, current_load_pickups):
        if index < 0:
            return 0
        distance = 0
        if current_load_deliveries == 0 and current_load_pickups == 0:
            distance += dfs(index - 1, 0, 0)
        if deliveries[index] > 0 or pickups[index] > 0:
            if current_load_deliveries < cap:
                to_deliver = min(cap - current_load_deliveries, deliveries[index])
                current_load_deliveries += to_deliver
                deliveries[index] -= to_deliver
            if current_load_pickups < cap:
                to_pickup = min(cap - current_load_pickups, pickups[index])
                current_load_pickups += to_pickup
                pickups[index] -= to_pickup
            distance += (index + 1) + dfs(index, current_load_deliveries, current_load_pickups)
        return distance

    return dfs(n - 1, 0, 0)

