def solution(n, l, r):
    def count_ones(n, l, r):
        if n == 0:
            return 0
        length = 3 ** n
        mid = length // 3
        if r <= mid:
            return count_ones(n - 1, l, r)
        elif l >= 2 * mid:
            return count_ones(n - 1, l - 2 * mid, r - 2 * mid)
        else:
            left_count = count_ones(n - 1, l, mid)
            right_count = count_ones(n - 1, 0, r - 2 * mid)
            return left_count + right_count + (max(0, min(r, 2 * mid) - max(l, mid)))

    return count_ones(n, l, r)

def solution(n, l, r):
