def solution(k, ranges):
    hailstone_sequence = []
    while k != 1:
        hailstone_sequence.append(k)
        if k % 2 == 0:
            k //= 2
        else:
            k = 3 * k + 1
    hailstone_sequence.append(1)

    hailstone_sequence = [min(x, 10**6) for x in hailstone_sequence]

    n = len(hailstone_sequence)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + hailstone_sequence[i]
        if prefix_sum[i + 1] > 10**9:
            prefix_sum[i + 1] = 10**9

    result = []
    for start, end in ranges:
        if end < 0 or start >= n:
            result.append(0)
        else:
            start = max(start, 0)
            end = min(end + 1, n)
            result.append(prefix_sum[end] - prefix_sum[start])

    return result

