    for digit in number:
        while k > 0 and stack and stack[-1] < digit:
            stack.pop()
            k -= 1
        stack.append(digit)
    return ''.join(stack[:-k]) if k else ''.join(stack)

def solution(number, k):
    if k == 0:
        return number
    if len(number) == k:
        return '0'

    max_number = ''
    for i in range(len(number) - k + 1):
        current = number[i]
        next_number = number[i + 1:i + 1 + (len(number) - i - 1 - (k - 1))]
        candidate = current + solution(next_number, k - 1)
        if candidate > max_number:
            max_number = candidate

    return max_number

def solution(name):
    def move_cost(c):
        return min(ord(c) - ord('A'), ord('Z') - ord(c) + 1)

    def calculate_position(index):
        if index >= len(name):
            return 0
        return move_cost(name[index]) + calculate_position(index + 1)

    def calculate_min_move(index, direction):
        if index < 0 or index >= len(name):
            return float('inf')
        return index + calculate_min_move(index + direction, direction)

    vertical_moves = calculate_position(0)
    horizontal_moves = min(calculate_min_move(0, 1), calculate_min_move(0, -1))

    return vertical_moves + horizontal_moves

def solution(name):
    def move_cursor(pos, name):
        if pos == len(name):
            return 0
        up_down = min(ord(name[pos]) - ord('A'), ord('Z') - ord(name[pos]) + 1)
        return up_down + move_cursor(pos + 1, name)

    def find_min_moves(pos, name, left_moves, right_moves):
        if pos == len(name):
            return left_moves + right_moves
        left = find_min_moves(pos + 1, name, left_moves + 1, right_moves)
        right = find_min_moves(pos - 1 if pos > 0 else len(name) - 1, name, left_moves, right_moves + 1)
        return min(left, right)

    vertical_moves = move_cursor(0, name)
    horizontal_moves = find_min_moves(0, name, 0, 0)
    return vertical_moves + horizontal_moves

