def solution(numbers):
    def recursive_combine(nums):
        if len(nums) == 1:
            return nums[0]
        max_num = ''
        for i in range(len(nums)):
            next_nums = nums[:i] + nums[i+1:]
            combined = nums[i] + recursive_combine(next_nums)
            max_num = max(max_num, combined)
        return max_num

    str_numbers = list(map(str, numbers))
    return str(recursive_combine(str_numbers))

import heapq

def solution(scoville, K):
    heapq.heapify(scoville)

    def mix():
        if scoville[0] >= K:
            return 0
        first = heapq.heappop(scoville)
        second = heapq.heappop(scoville)
        new_scoville = first + (second * 2)
        heapq.heappush(scoville, new_scoville)
        return 1 + mix()

    return mix()

def solution(scoville, K):
    if not scoville:
        return -1
    scoville.sort()
    if scoville[0] >= K:
        return 0
    if len(scoville) == 1:
        return -1
    first = scoville.pop(0)
    second = scoville.pop(0)
    new_scoville = first * 2
    scoville.append(new_scoville)
    return 1 + solution(scoville, K)

def solution(priorities, location):
    def process(priorities, location, order):
        if not priorities:
            return order

        max_priority = max(priorities)
        if priorities[0] == max_priority:
            order.append(1)
            return process(priorities[1:], location - 1, order)
        else:
            priorities.append(priorities.pop(0))
            if location == 0:
                location = len(priorities) - 1
            else:
                location -= 1
            return process(priorities, location, order)

    order = []
    result = process(priorities, location, order)
    return len(result) - result[::-1].index(1) if 1 in result else 0

def solution(priorities, location):
    from collections import deque
    queue = deque([(p, i) for i, p in enumerate(priorities)])
    order = 0

    while queue:
        current = queue.popleft()
        if any(current[0] < other[0] for other in queue):
            queue.append(current)
        else:
            order += 1
            if current[1] == location:
                return order

def solution(priorities, location):
    def recursive_process(priorities, location, order):
        if not priorities:
            return order
        current = priorities[0]
        if any(current < p for p in priorities[1:]):
            priorities.append(current)
            return recursive_process(priorities[1:], location - 1 if location > 0 else len(priorities) - 1, order)
        else:
            order += 1
            if location == 0:
                return order
            return recursive_process(priorities[1:], location - 1, order)

    return recursive_process(priorities, location, 0)

