def solution(n, t, m, p):
    def convert_to_base(num, base):
        if num == 0:
            return '0'
        digits = []
        while num:
            digits.append(int(num % base))
            num //= base
        return ''.join(str(x) if x < 10 else chr(x - 10 + ord('A')) for x in digits[::-1])

    result = []
    current_number = 0
    while len(result) < t * m:
        result.append(convert_to_base(current_number, n))
        current_number += 1

    answer = ''.join(result[i] for i in range(len(result)) if i % m == p - 1)
    return answer[:t]

def solution(n, t, m, p):
    def convert_to_n_base(num, base):
        if num == 0:
            return ''
        return convert_to_n_base(num // base, base) + '0123456789ABCDEF'[num % base]

    def get_digit(num, base, position):
        if position == 0:
            return num % base
        return get_digit(num // base, base, position - 1)

    sequence = ''.join(convert_to_n_base(i, n) for i in range(t * m))
    return sequence[p - 1] if p - 1 < len(sequence) else ''

def solution(files):
