def solution(files):
    if len(files) <= 1:
        return files

    def extract_key(file):
        head, number, tail = '', '', ''
        i = 0
        while i < len(file) and not file[i].isdigit():
            head += file[i]
            i += 1
        while i < len(file) and file[i].isdigit():
            number += file[i]
            i += 1
        tail = file[i:]
        return (head.lower(), int(number), tail)

    mid = len(files) // 2
    left = solution(files[:mid])
    right = solution(files[mid:])

    sorted_files = []
    while left or right:
        if not left:
            sorted_files.append(right.pop(0))
        elif not right:
            sorted_files.append(left.pop(0))
        else:
            left_key = extract_key(left[0])
            right_key = extract_key(right[0])
            if left_key <= right_key:
                sorted_files.append(left.pop(0))
            else:
                sorted_files.append(right.pop(0))

    return sorted_files

