def solution(msg):
    def compress_lzw(s, dictionary, index):
        if not s:
            return []
        longest_word = ''
        for i in range(len(s)):
            if s[:i + 1] in dictionary:
                longest_word = s[:i + 1]
            else:
                break
        result = [dictionary[longest_word]]
        dictionary[s[:len(longest_word) + 1]] = index
        return result + compress_lzw(s[len(longest_word):], dictionary, index + 1)

    dictionary = {chr(i): i - 64 for i in range(65, 91)}
    return compress_lzw(msg, dictionary, len(dictionary) + 1)

def solution(m, musicinfos):
    def convert_melody(melody):
        melody = melody.replace('C#', 'c').replace('D#', 'd').replace('F#', 'f').replace('G#', 'g').replace('A#', 'a')
        return melody

    def get_play_time(start, end):
        h1, m1 = map(int, start.split(':'))
        h2, m2 = map(int, end.split(':'))
        return (h2 - h1) * 60 + (m2 - m1)

    m = convert_melody(m)
    candidates = []

    for info in musicinfos:
        start, end, title, melody = info.split(',')
        play_time = get_play_time(start, end)
        melody = convert_melody(melody)
        full_melody = (melody * (play_time // len(melody) + 1))[:play_time]
        if m in full_melody:
            candidates.append((play_time, title))

    if not candidates:
        return "(None)"

    candidates.sort(key=lambda x: (-x[0], x[1]))
    return candidates[0][1]

