        union = len(set1.union(set2))
        return intersection / union if union != 0 else 0

    def group_titles(titles, index=0, groups=None):
        if groups is None:
            groups = []
        if index >= len(titles):
            return groups

        current_title = titles[index]
        current_set = set(current_title)
        found_group = False

        for group in groups:
