                for x in range(len(piece)):
                    for y in range(len(piece[0])):
                        table[i - len(piece) + x][j - len(piece[0]) + y] = 0

    return 1 if backtrack(game_board, pieces, 0) else 0

def solution(n, k, cmd):
    from collections import deque

    deleted = set()
    stack = deque()
    current = k

    for command in cmd:
        if command[0] == 'U':
            x = int(command[2:])
            for _ in range(x):
                while current > 0 and current - 1 in deleted:
                    current -= 1
                current -= 1
        elif command[0] == 'D':
