            for _ in range(x):
                while current < n - 1 and current + 1 in deleted:
                    current += 1
                current += 1
        elif command[0] == 'C':
            deleted.add(current)
            stack.append(current)
            while current < n - 1 and current + 1 in deleted:
                current += 1
            while current > 0 and current - 1 in deleted:
                current -= 1
            if current in deleted:
                current = None
                if current is None:
                    current = stack[-1] if stack else -1
        elif command[0] == 'Z':
            restored = stack.pop()
