        def __init__(self, x, y):
            self.x = x
            self.y = y
            self.left = None
            self.right = None

    def insert(root, node):
        if root is None:
            return node
        if node.x < root.x:
            root.left = insert(root.left, node)
        else:
            root.right = insert(root.right, node)
        return root

    def preorder(node, result):
        if node:
            result.append([node.x, node.y])
            preorder(node.left, result)
            preorder(node.right, result)

    def inorder(node, result):
        if node:
            inorder(node.left, result)
            result.append([node.x, node.y])
            inorder(node.right, result)

    def postorder(node, result):
        if node:
            postorder(node.left, result)
            postorder(node.right, result)
            result.append([node.x, node.y])

    nodes = [Node(x, y) for x, y in nodeinfo]
    root = None
    for node in nodes:
        root = insert(root, node)

    preorder_result = []
    inorder_result = []
    postorder_result = []

    preorder(root, preorder_result)
    inorder(root, inorder_result)
    postorder(root, postorder_result)

    return [preorder_result, inorder_result, postorder_result]

