def solution(works, n):
    import heapq
    if sum(works) <= n:
        return 0
    works = [-work for work in works]
    heapq.heapify(works)
    for _ in range(n):
        largest = heapq.heappop(works)
        if largest < 0:
            heapq.heappush(works, largest + 1)
    return sum(work ** 2 for work in works)

def solution(works, n):
    if n <= 0:
        return sum(x**2 for x in works)
    if not works:
        return 0
    max_work = max(works)
    if max_work == 0:
        return 0
    works[works.index(max_work)] -= 1
    return solution(works, n - 1)

def solution(n, cores):
    def assign_tasks(n, cores, times):
        if n == 0:
            return times.index(min(times))
        min_time = min(times)
        idx = times.index(min_time)
        times[idx] += cores[idx]
        return assign_tasks(n - 1, cores, times)

    return assign_tasks(n, cores, [0] * len(cores)) + 1

def solution(n, cores):
    if n <= len(cores):
        return n

    left, right = 1, max(cores) * n
    while left < right:
        mid = (left + right) // 2
        total_jobs = sum(mid // core for core in cores)

        if total_jobs < n:
            left = mid + 1
        else:
            right = mid

    total_jobs = sum((left - 1) // core for core in cores)
    for i in range(len(cores)):
        if left % cores[i] == 0:
            total_jobs += 1
            if total_jobs == n:
                return i + 1

    return -1

def solution(n, cores):
    def schedule(n, cores, times):
        if n == 0:
            return times.index(min(times))
        min_time = min(times)
        next_core = times.index(min_time)
        times[next_core] += cores[next_core]
        return schedule(n - 1, cores, times)

    return schedule(n - len(cores), cores, cores.copy()) if n > len(cores) else n - 1

def solution(n, money):
