    def find_min_distance(customers, lockers, index):
        if index == len(customers):
            return float('inf')

        min_dist = float('inf')
        for locker in lockers:
            if locker not in used_lockers:
                used_lockers.add(locker)
                current_dist = 0
                for i in range(index + 1):
                    current_dist += distance(customers[i], locker)
                min_dist = min(min_dist, current_dist + find_min_distance(customers, lockers, index + 1))
                used_lockers.remove(locker)

        return min_dist

    customers = [(i // m, i % m) for i in range(n * m)]
    used_lockers = set()
    return find_min_distance(customers, customers, 0)

def solution(n, m, edge_list, k, gps_log):
    from collections import Counter

    def count_visits(log, counter):
