def solution(n, m, edge_list, k, gps_log):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in edge_list:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start, end):
        queue = deque([start])
        visited = {start}
        parent = {start: None}

        while queue:
            node = queue.popleft()
            if node == end:
                path = []
                while node is not None:
                    path.append(node)
                    node = parent[node]
                return path[::-1]
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    parent[neighbor] = node
                    queue.append(neighbor)
        return []

    valid_path = bfs(gps_log[0], gps_log[-1])
    if not valid_path:
        return -1

    valid_set = set(valid_path)
    errors = sum(1 for pos in gps_log if pos not in valid_set)

    return errors

