def solution(m, n, board):
    from collections import deque

    def is_removable(x1, y1, x2, y2):
        if x1 == x2:
            return True
        if y1 == y2:
            return True
        if x1 > x2:
            x1, x2 = x2, x1
        if y1 > y2:
            y1, y2 = y2, y1
        path = [(x1, y1), (x2, y1), (x2, y2)]
        for i in range(len(path) - 1):
            if not is_clear(path[i], path[i + 1]):
                return False
        return True

    def is_clear(start, end):
        x1, y1 = start
        x2, y2 = end
        if x1 == x2:
            for y in range(min(y1, y2) + 1, max(y1, y2)):
                if board[x1][y] != '0':
                    return False
            return True
        else:
            for x in range(min(x1, x2) + 1, max(x1, x2)):
                if board[x][y1] != '0':
                    return False
            return True

    def remove_tiles(x1, y1, x2, y2):
        board[x1][y1] = '0'
        board[x2][y2] = '0'

    def bfs(start):
        queue = deque([start])
        visited = set()
        while queue:
            x, y = queue.popleft()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited and board[nx][ny] != '0':
                    visited.add((nx, ny))
                    queue.append((nx, ny))
        return visited

    def find_pairs():
        pairs = []
        for i in range(m):
            for j in range(n):
                if board[i][j] != '0':
                    for x in range(m):
                        for y in range(n):
                            if (i, j) != (x, y) and board[x][y] == board[i][j] and is_removable(i, j, x, y):
                                pairs.append(((i, j), (x, y)))
        return pairs

    while True:
        pairs = find_pairs()
        if not pairs:
            break
        for (x1, y1), (x2, y2) in pairs:
            remove_tiles(x1, y1, x2, y2)

    return sum(row.count('0') for row in board)

def solution(m, n, board):
    def can_remove(x1, y1, x2, y2):
        if x1 == x2:
            return all(board[x1][min(y1, y2) + i] == '0' for i in range(abs(y1 - y2) + 1))
        elif y1 == y2:
            return all(board[min(x1, x2) + i][y1] == '0' for i in range(abs(x1 - x2) + 1))
        else:
            return (all(board[x1][y] == '0' for y in range(min(y1, y2), max(y1, y2) + 1)) and
                    all(board[x][y2] == '0' for x in range(min(x1, x2), max(x1, x2) + 1))) or \
                   (all(board[x2][y] == '0' for y in range(min(y1, y2), max(y1, y2) + 1)) and
                    all(board[x][y1] == '0' for x in range(min(x1, x2), max(x1, x2) + 1)))

    def remove_tiles():
        for i in range(m):
            for j in range(n):
                if board[i][j] != '0':
                    tile = board[i][j]
                    for x in range(m):
                        for y in range(n):
                            if (x != i or y != j) and board[x][y] == tile:
                                if can_remove(i, j, x, y):
                                    board[i][j] = board[x][y] = '0'
                                    if remove_tiles():
                                        return True
                                    board[i][j] = tile
                                    board[x][y] = tile
                    return False
        return True

    while remove_tiles():
        pass

    return sum(row.count('0') for row in board)

