def solution(m, n, city_map):
    mod = 1000000007
    dp = [0] * n
    dp[0] = 1 if city_map[0][0] == 0 else 0

    for i in range(m):
        for j in range(n):
            if city_map[i][j] == 1:
                dp[j] = 0
            else:
                if j > 0:
                    dp[j] = (dp[j] + dp[j - 1]) % mod
                if i > 0 and j == 0:
                    dp[j] = dp[j] % mod

    return dp[n - 1]

