def solution(sentence):
    def filter_special_chars(s, index):
        if index == len(s):
            return ""
        char = s[index]
        if char.isalnum() or char.isspace():
            return char + filter_special_chars(s, index + 1)
        return filter_special_chars(s, index + 1)

    cleaned_sentence = filter_special_chars(sentence, 0)
    return "광고" in cleaned_sentence
